To create an app that integrates Draw and Sketch Art with JavaScript into our RUBBI and UPayU Bridge Payment integrations, we'll need to follow these steps:

**Step 1: Set up a new Node.js project**

Create a new directory for your project and initialize a new Node.js project using `npm init`.

**Step 2: Install required dependencies**

Install the required dependencies, including `express`, `axios`, and `postgres` for the database connection. You can use `npm install` or `yarn add` to install the dependencies.

**Step 3: Create a database schema**

Create a database schema to store payment information and webhook events. You can use a database like PostgreSQL to store this information.

**Step 4: Set up API endpoints**

Create API endpoints to handle payment requests, payment status updates, and webhook events. You can use `express` to create these endpoints.

**Step 5: Integrate Draw and Sketch Art functionality**

Integrate Draw and Sketch Art functionality using JavaScript. You can use libraries like `canvas` or `sketch.js` to create a drawing interface.

**Step 6: Integrate UPayU Bridge Payment**

Integrate the UPayU Bridge Payment functionality into your application. You can use the UPayU Bridge API to create and capture payments.

**Step 7: Integrate RUBBI Payment**

Integrate the RUBBI Payment functionality into your application. You can use the RUBBI Payment API to create and capture payments.

**Step 8: Implement Webhook functionality**

Implement Webhook functionality to receive payment status updates and webhook events from the UPayU Bridge and RUBBI Payment APIs.

Here's a high-level example of how you could implement this:

**server.js**
```javascript
const express = require('express');
const app = express();
const port = 3000;

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const upayuService = require('./services/upayuService');
const rubiService = require('./services/rubiService');
const webhookService = require('./services/webhookService');

app.post('/payments', upayuService.createPayment);
app.post('/payments/:transactionId/capture', upayuService.capturePayment);
app.post('/webhooks', webhookService.handleWebhook);

app.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});
```
**services/upayuService.js**
```javascript
const axios = require('axios');
const rubiService = require('./rubiService');

class UpayuService {
  async createPayment(amount, currency, paymentMethod, metadata) {
    try {
      const response = await axios.post('https://api.upayu.com/v2/payments', {
        amount,
        currency,
        payment_method: paymentMethod,
        metadata,
      }, {
        headers: {
          'Authorization': 'Bearer YOUR_API_KEY',
          'Content-Type': 'application/json',
        },
      });
      // Save payment to database
      await rubiService.savePayment(response.data);
      return response.data;
    } catch (error) {
      console.error('UPayU API Error:', error.response?.data || error.message);
      throw error;
    }
  }

  async capturePayment(transactionId) {
    try {
      const response = await axios.post(`https://api.upayu.com/v2/payments/${transactionId}/capture`, {}, {
        headers: {
          'Authorization': 'Bearer YOUR_API_KEY',
          'Content-Type': 'application/json',
        },
      });
      // Update payment status in database
      await rubiService.updatePaymentStatus(response.data);
      return response.data;
    } catch (error) {
      console.error('Capture Error:', error.response?.data || error.message);
      throw error;
    }
  }
}

module.exports = new UpayuService();
```
**services/rubiService.js**
```javascript
const axios = require('axios');
const { Pool } = require('pg');

class RubiService {
  async savePayment(payment) {
    try {
      const pool = new Pool({
        user: 'YOUR_DB_USER',
        host: 'YOUR_DB_HOST',
        database: 'YOUR_DB_NAME',
        password: 'YOUR_DB_PASSWORD',
        port: 'YOUR_DB_PORT',
      });
      await pool.query('INSERT INTO payments (transaction_id, amount, currency, status, payment_method, metadata) VALUES ($1, $2, $3, $4, $5, $6)', [
        payment.transaction_id,
        payment.amount,
        payment.currency,
        'pending',
        payment.payment_method,
        payment.metadata,
      ]);
    } catch (error) {
      console.error('Database Error:', error);
    }
  }

  async updatePaymentStatus(payment) {
    try {
      const pool = new Pool({
        user: 'YOUR_DB_USER',
        host: 'YOUR_DB_HOST',
        database: 'YOUR_DB_NAME',
        password: 'YOUR_DB_PASSWORD',
        port: 'YOUR_DB_PORT',
      });
      await pool.query('UPDATE payments SET status = $1 WHERE transaction_id = $2', [
        'completed',
        payment.transaction_id,
      ]);
    } catch (error) {
      console.error('Database Error:', error);
    }
  }
}

module.exports = new RubiService();
```
This is just a high-level example of how you could implement this. You'll need to customize the code to fit your specific requirements and handle errors, etc.

